private static void removeTransitionForMultiByteSet(ByteState state, InputMultiByteSet multiByteSet, SingleByteTransition transition) {
    for (MultiByte multiByte : multiByteSet.getMultiBytes()) {
        removeTransitionForBytes(state, multiByte.getBytes(), 0, transition);
    }
}
